def handoff_distances(parent, queries):
    n = len(parent)
    children = [[] for _ in range(n)]
    root = 0
    for i, p in enumerate(parent):
        if p < 0:
            root = i
        else:
            children[p].append(i)
    depth = [0] * n
    order = [root]
    for node in order:
        for child in children[node]:
            depth[child] = depth[node] + 1
            order.append(child)
    up = [[root if p < 0 else p for p in parent]]
    levels = max(1, max(depth).bit_length())
    for _ in range(levels - 1):
        prev = up[-1]
        up.append([prev[v] for v in prev])
    answers = []
    for a, b in queries:
        da, db = depth[a], depth[b]
        if da < db:
            a, b = b, a
        gap, k = abs(da - db), 0
        while gap:
            if gap & 1:
                a = up[k][a]
            gap >>= 1
            k += 1
        if a != b:
            for k in range(levels - 1, -1, -1):
                if up[k][a] != up[k][b]:
                    a, b = up[k][a], up[k][b]
            a = up[0][a]
        answers.append(da + db - 2 * depth[a])
    return answers

